// =========================================================================
// 1. REQUETE : Préparation du pipeline d'agrégation sécurisé
// =========================================================================
var pipeline = [
    // Étape A : Trouver le document système par son ID unique 'init'
    { $match: { "_id": "init" } },

    // Étape B : Extraire 'escape_details' à la racine. S'il n'existe pas, renvoie un objet vide {}
    {
        $replaceRoot: {
            newRoot: { $ifNull: ["$escape_details", {}] }
        }
    }
];

var options = {};

// Encapsulation obligatoire pour la syntaxe node-red-contrib-mongodb4
msg.payload = [pipeline, options];
msg.operation = "aggregate";
msg.topic = "load_escape_details";

return msg;

// =========================================================================
// 1. RELOAD : ON ENVOIE UNIQUEMENT SUR LA SORTIE 3 (BYPASS VERS LINK OUT)
// =========================================================================
if (msg.topic === "reload_escape_details") {
    msg.payload = {};
    return [null, null, msg];
}

// =========================================================================
// 2. SAVE : DISTRIBUTION VERS EXEC (1) ET MONGODB4 (2) - SORTIE 3 BLOQUEE
// =========================================================================
if (msg.topic === "save_escape_details") {
    if (!msg.payload || !msg.payload.escape_name) return null;

    var hostname = msg.payload.escape_name;
    hostname = hostname.replace(/[^a-zA-Z0-9\s]/g, '').replace(/ /g, '').trim();

    // Sauvegarde dans le contexte global de l'Escape Game
    global.set("config.escape_name", hostname);

    // Préparation pour Sortie 1 (Bash - Nom machine du Raspberry Pi)
    var msgBash = {
        _msgid: msg._msgid,
        topic: msg.topic,
        payload: "sudo hostnamectl set-hostname " + hostname
    };

    // Préparation pour Sortie 2 (MongoDB4 moderne)
    // Format d'arguments obligatoire : [ query, updateDoc, options ]
    var msgMongo = {
        _msgid: msg._msgid,
        topic: msg.topic,
        operation: "updateOne",
        payload: [
            { "_id": "init" },
            { $set: { "escape_details.escape_name": hostname } },
            { "upsert": true }
        ]
    };

    // Envoi simultané sur les sorties 1 et 2 uniquement
    return [msgBash, msgMongo, null];
}

return null;

// =========================================================================
// 1. ANALYSE ET DISTRIBUTION : GESTION SECURISEE DU PAYLOAD ET DES ERREURS
// =========================================================================
if (msg.rc && msg.rc.code === 255) {
    var detailObj = { ssid: "aucune connexion" };
    flow.set('WIFI.Detail', detailObj);
    msg.topic = "wifiDetail";
    msg.payload = detailObj;
    return msg;
}
var payload = typeof msg.payload === "string" ? msg.payload : String(msg.payload || "");
if (payload.includes("Link encap") || payload.includes("flags=")) {
    var ip = "aucune connexion", mask = "aucune connexion", broadcast = "aucune connexion";
    var matchIp = payload.match(/inet ([0-9\.]+)/);
    var matchMask = payload.match(/netmask ([0-9\.]+)/);
    var matchBcast = payload.match(/broadcast ([0-9\.]+)/);
    if (matchIp) ip = matchIp[1];
    if (matchMask) mask = matchMask[1];
    if (matchBcast) broadcast = matchBcast[1];
    var infoObj = { ip: ip, mask: mask, broadcast: broadcast };
    flow.set('WIFI.Info', infoObj);
    msg.topic = "wifiInfo";
    msg.payload = infoObj;
} else if (payload.includes("ESSID:") || msg.topic === "getCurrentSSID") {
    var ssid = "aucune connexion";
    var matchSsid = payload.match(/ESSID:"([^"]+)"/);
    if (matchSsid) ssid = matchSsid[1];
    var detailObj = { ssid: ssid };
    flow.set('WIFI.Detail', detailObj);
    msg.topic = "wifiDetail";
    msg.payload = detailObj;
} else {
    var ssids = payload.split('\n').filter(s => !!s);
    ssids = [...new Set(ssids)];
    flow.set('WIFI.ssids', ssids);
    msg.topic = "ssids";
    msg.payload = ssids;
}
return msg;

// =========================================================================
// 1. ROUTAGE & TRAITEMENT : DOUBLE ENTREE (UI / RETOUR EXEC) ET TRIPLE SORTIE
// =========================================================================
if (msg.topic === "reload_wifi_details") {
    msg.payload = {};
    return [null, null, msg];
}
if (msg.topic === "save_wifi_details") {
    msg.ssid = msg.payload.ssid;
    msg.payload = 'sudo nmcli d wifi connect "' + msg.payload.ssid + '" password "' + msg.payload.password + '" ifname wlan0';
    return [msg, null, null];
}
if (msg.rc && msg.rc.code === 4) {
    msg.payload = 'sudo nmcli connection delete id "' + msg.ssid + '"';
    return [null, msg, null];
} else if (msg.rc) {
    return [null, null, msg];
}
return null;

// =========================================================================
// 1. REQUETE : PIPELINE D'AGREGATION DES PIECES POUR MONGODB4
// =========================================================================
var pipeline = [
    // Étape A : Trouver le document système par son ID unique 'init'
    { $match: { "_id": "init" } },

    // Étape B : Éclater le tableau pour trier les éléments (préserve le document s'il est vide)
    { $unwind: { path: "$rooms_list", preserveNullAndEmptyArrays: true } },

    // Étape C : Trier numériquement les pièces par leur numéro d'ordre
    { $sort: { "rooms_list.number": 1 } },

    // Étape D : Extraire 'rooms_list' à la racine. S'il n'existe pas, renvoie un objet vide {}
    {
        $replaceRoot: {
            newRoot: { $ifNull: ["$rooms_list", {}] }
        }
    }
];

var options = {};

// =========================================================================
// 2. ENCAPSULATION : PARAMETRAGE STRICT POUR NODE-RED-CONTRIB-MONGODB4
// =========================================================================
// Structuration obligatoire sous forme de tableau JavaScript [ pipeline, options ]
msg.payload = [pipeline, options];

// L'opération est laissée vide dans le nœud physique et injectée ici dynamiquement
msg.operation = "aggregate";
msg.topic = "load_rooms_list";

return msg;

// =========================================================================
// 1. VARIABLE GLOBALE : CAPTURE DU NOMBRE CONFIGURÉ D'ENCEINTES
// =========================================================================
msg.NumberOfSpeakers = global.get('Memory.Speaker.number_of_speakers') || 0;

// =========================================================================
// 2. REQUETE : PIPELINE D'AGREGATION CLE/VALEUR EN TABLEAU MONGODB4
// =========================================================================
var pipeline = [
    // Étape A : Trouver le document système par son ID unique 'init'
    { $match: { "_id": "init" } },

    // Étape B : Éclater le tableau de chaînes brutes en capturant l'index d'origine (0, 1, 2...)
    {
        $unwind: {
            path: "$speakers_list",
            includeArrayIndex: "speaker_index",
            preserveNullAndEmptyArrays: true
        }
    },

    // Étape C : Reconstruction dynamique au format strict { index: "valeur" }
    {
        $project: {
            "speaker_object": {
                $arrayToObject: [
                    [
                        {
                            // Conversion de l'index numérique en chaîne de caractères pour MongoDB
                            "k": { $toString: "$speaker_index" },
                            "v": "$speakers_list"
                        }
                    ]
                ]
            }
        }
    },

    // Étape D : Remonter cet objet à la racine du payload du tableau
    {
        $replaceRoot: {
            newRoot: { $ifNull: ["$speaker_object", {}] }
        }
    }
];

var options = {};

// =========================================================================
// 3. ENCAPSULATION : STRUCTURATION OBLIGATOIRE POUR NODE-RED-CONTRIB-MONGODB4
// =========================================================================
msg.payload = [pipeline, options];
msg.operation = "aggregate";
msg.topic = "load_speakers_list";

return msg;

// =========================================================================
// 1. MUTATION : CONFIGURATION DES ARGUMENTS EXIGES PAR MONGODB4
// =========================================================================
// Ciblage direct du document racine unique 'init' de ta collection config_system
var query = { "_id": "init" };

// Reprise stricte de ton écrasement atomique de tableau
var updateDoc = {
    $set: {
        "speakers_list": msg.payload.speakers_name
    }
};

var options = {};

// =========================================================================
// 2. ENCAPSULATION : STRUCTURATION STRICTE DU PAYLOAD TABLEAU
// =========================================================================
// Passage obligatoire au format moderne de tableau [ query, updateDoc, options ]
msg.payload = [query, updateDoc, options];

// Injection de l'opération requise par le pilote node-red-contrib-mongodb4
msg.operation = "updateOne";

return msg;

// =========================================================================
// 1. CAS RELOAD_ROOM : ON PASSE DIRECTEMENT SUR LA SORTIE POUR RAFRAICHIR
// =========================================================================
if (msg.topic === "reload_room") { return [null, msg]; }

// =========================================================================
// 2. CAS SAVE_ROOM : AJOUT ($PUSH) OU MODIFICATION ($SET) D'UNE PIECE
// =========================================================================
if (msg.topic === "save_room") {
    var isNew = msg.payload._id === "new";
    var query = {}; var updateDoc = {}; var options = {};
    if (isNew) {
        query = { "_id": "init" };
        updateDoc = { $push: { "rooms_list": { "_id": msg._msgid, "number": msg.payload.number, "name": msg.payload.name } } };
    } else {
        query = { "_id": "init", "rooms_list._id": msg.payload._id };
        updateDoc = { $set: { "rooms_list.$.name": msg.payload.name } };
    }
    msg.payload = [query, updateDoc, options]; msg.operation = "updateOne"; return [msg, null];
}

// =========================================================================
// 3. CAS NEW_ORDER_ROOM : BOUCLE DE REORDONNANCEMENT SUITE AU DRAG & DROP
// =========================================================================
if (msg.topic === "new_order_room") {
    var order = msg.payload.new_order || [];
    order.forEach(function (id, index) {
        var msgLoop = { _msgid: msg._msgid, topic: msg.topic, operation: "updateOne", payload: [ { "_id": "init", "rooms_list._id": id }, { $set: { "rooms_list.$.number": index + 1 } }, {} ] };
        node.send([msgLoop, null]);
    });
    return null;
}

// =========================================================================
// 4. CAS DELETE_ROOM : SUPPRESSION ($PULL) + RENUMÉROTATION EN CASCADE
// =========================================================================
if (msg.topic === "delete_room") {
    var deletedId = msg.payload._id; var currentOrder = msg.payload.new_order || [];
    var msgDelete = { _msgid: msg._msgid, topic: msg.topic, operation: "updateOne", payload: [ { "_id": "init" }, { $pull: { "rooms_list": { "_id": deletedId } } }, {} ] };
    node.send([msgDelete, null]);
    var updatedOrder = [];
    currentOrder.forEach(function (id) { if (id !== deletedId) { updatedOrder.push(id); } });
    updatedOrder.forEach(function (id, index) {
        var msgReorder = { _msgid: msg._msgid, topic: msg.topic, operation: "updateOne", payload: [ { "_id": "init", "rooms_list._id": id }, { $set: { "rooms_list.$.number": index + 1 } }, {} ] };
        node.send([msgReorder, null]);
    });
    return null;
}
return null;

// =========================================================================
// 1. CONFIGURATION : CAPTURE DU DOSSIER REEL DEPUIS LES ALIGNEMENTS DU CLIENT
// =========================================================================
var data = msg.payload || {};
var folder = data.type || "";

// Contrôle de sécurité strict pour protéger le système de fichiers Linux du Pi
if (!folder) {
    node.error("Erreur : Propriété 'type' manquante dans msg.payload.");
    return null;
}

// Construction directe du chemin absolu sur ton Raspberry Pi sans conversion
var basePath = "/home/pi/Uploads/" + folder + "/";
msg.type = folder; // Maintien de la cohérence pour tes nœuds aval

// =========================================================================
// 2. CAS RENAME_FILE : COMMANDES DE RENOMMAGE APPLIQUEES SUR L'INDEX PAYLOAD -> SORTIE 1
// =========================================================================
if (msg.topic === "rename_file") {
    var oldName = data.oldName || "";
    var newName = data.newName || "";
    var cleanedNewName = newName.split(' ').join('_');

    // Génération de la commande système Linux mv (avec tes apostrophes d'origine)
    msg.payload = "mv " + basePath + "'" + oldName + "' " + basePath + cleanedNewName;
    return [msg, null, null]; // Sortie 1 vers Mv Command (exec)
}

// Injection du chemin complet requis pour le nœud File (delete) ou le Link Preview
msg.filename = basePath + (data.filename || "");

// =========================================================================
// 3. CAS DELETE_FILE : REDIRECTION EXCLUSIVE SUR LA SORTIE 2 VERS LE NOEUD FILE
// =========================================================================
if (msg.topic === "delete_file") {
    return [null, msg, null]; // Sortie 2 (Delete File) uniquement, Sortie 3 (Preview) coupée net !
}

// =========================================================================
// 4. CAS PREVIEW_FILE : REDIRECTION UNIQUE VERS LE LIEN DE PREVIEW SORTIE 3
// =========================================================================
if (msg.topic === "preview_file") {
    return [null, null, msg]; // Sortie 3 vers Link Preview uniquement
}

return null;

// =========================================================================
// 1. CONFIGURATION : INTERCEPTION DES METADONNEES DEPUIS TON CODE REEL
// =========================================================================
var file = msg.req.files[0];
var mimetype = file.mimetype;
var fieldname = file.fieldname;
var originalname = file.originalname;

var folder = "";

// =========================================================================
// 2. AIGUILLAGE : SELECTION DU DOSSIER REEL ET CONFIGURATION DES FILENAMES
// =========================================================================
if (mimetype.includes("image")) {
    folder = "Images";
    // CORRECTION : Passage explicite de l'extension extraite en minuscules (.toLowerCase())
    var ext = originalname.split('.').pop().toLowerCase();
    msg.filename = '/home/pi/Uploads/Images/' + fieldname + '.' + ext;
}
else if (mimetype.includes("audio")) {
    folder = "Sounds";
    // Pour l'audio, on conserve ton format d'origine géré par le sélecteur du GM
    msg.filename = '/home/pi/Uploads/Sounds/' + fieldname + '.' + originalname;
    msg.format = originalname;
}
else if (mimetype === "video/mp4") {
    folder = "Videos";
    var ext = originalname.split('.').pop().toLowerCase();
    msg.filename = '/home/pi/Uploads/Videos/' + fieldname + '.' + ext;
}
else if (mimetype.includes("font")) {
    folder = "Fonts";
    var ext = originalname.split('.').pop().toLowerCase();
    msg.filename = '/home/pi/Uploads/Fonts/' + fieldname + '.' + ext;
}
else {
    // Cas Sécurité : Branche du ELSE de ton switch d'origine
    msg.payload = "Ce type de fichier n'est pas autorisé !";
    return [null, null, msg];
}

// Extraction du buffer binaire d'origine pour l'écriture ou la conversion
msg.payload = file.buffer;

// Construction de ton message texte de succès d'origine avec l'extension nettoyée
var finalExt = folder === "Sounds" ? originalname : originalname.split('.').pop().toLowerCase();
var successMsg = 'Fichier ' + originalname + ' enregistré sous ' + fieldname + '.' + finalExt;

// Pre-configuration du message de retour synchrone de succès
var msgResponse = RED.util.cloneMessage(msg);
msgResponse.payload = successMsg;

// =========================================================================
// 3. ROUTAGE : DISPATCHING STRICT SELON TES BRANCHES D'ORIGINE
// =========================================================================
if (folder === "Sounds") {
    return [null, msg, msgResponse];
} else {
    return [msg, null, msgResponse];
}

// =========================================================================
// 1. REQUETE : PIPELINE D'AGREGATION DES VOIX POUR MONGODB4 (SANS TRI)
// =========================================================================
var pipeline = [
    // Étape A : Trouver le document système unique par son ID 'init'
    { $match: { "_id": "init" } },

    // Étape B : Éclater le tableau des voix pour un traitement unitaire
    { $unwind: { path: "$voices_list", preserveNullAndEmptyArrays: true } },

    // Étape C : Extraire voices_list à la racine et sécuriser si null ou manquant
    {
        $replaceRoot: {
            newRoot: { $ifNull: ["$voices_list", {}] }
        }
    }
];

var options = {};

// =========================================================================
// 2. ENCAPSULATION : PARAMETRAGE STRICT POUR NODE-RED-CONTRIB-MONGODB4
// =========================================================================
msg.payload = [pipeline, options];
msg.operation = "aggregate";
msg.topic = "load_voices_list";

return msg;

// SÉCURISATION PRÉALABLE CONTRE LES PAQUETS VIDES OU MAL FORMÉS
if (!msg || !msg.topic) return null;

// =========================================================================
// 1. CAS RELOAD_VOICES_LIST : LE SIGNAL COURT-CIRCUITE LA BASE ET SORT SUR LA SORTIE 2
// =========================================================================
if (msg.topic === "reload_voices_list") {
    var msgDirectRefresh = { "topic": "load_voices_list", "payload": {} };
    return [null, msgDirectRefresh];
}

// =========================================================================
// 2. CAS SAVE_VOICE : ROUTAGE UNIQUE UNIFIÉ ET ADAPTATION CHIRURGICALE
// =========================================================================
if (msg.topic === "save_voice") {
    var data = msg.payload || {};
    var queryVoice = {};
    var saveVoiceQuery = {};

    // centralisation et factorisation des champs pour eviter la duplication de code (Section 6)
    var voicesObj = {
        "name": data.name || "",
        "edge_id": data.edge_id || "",
        "pitch": data.pitch || "",
        "rate": data.rate || "",
        "volume": data.volume || ""
    };

    // si la voix est nouvelle (injection de l'id msg._msgid via push)
    if (data._id === "new") {
        queryVoice = { "_id": "init" };
        saveVoiceQuery = {
            "$push": {
                "voices_list": Object.assign({ "_id": msg._msgid }, voicesObj)
            }
        };
    }
    // si la voix existe deja (filtrage de l'id et mise a jour globale via set)
    else {
        queryVoice = {
            "_id": "init",
            "voices_list._id": data._id
        };
        saveVoiceQuery = {
            "$set": {
                "voices_list.$": Object.assign({ "_id": data._id }, voicesObj)
            }
        };
    }

    // formatage strict [query, update, options] pour le driver mongodb4 (Section 6)
    msg.payload = [queryVoice, saveVoiceQuery, { "upsert": false }];
    msg.operation = "updateOne";
    return [msg, null];
}

// =========================================================================
// 3. CAS DELETE_VOICE : SUPPRESSION CHIRURGICALE DANS LE TABLEAU VOICES_LIST VIA $PULL
// =========================================================================
if (msg.topic === "delete_voice") {
    var queryDel = { "_id": "init" };
    var updateDel = {
        "$pull": {
            "voices_list": {
                "_id": msg.payload._id
            }
        }
    };

    msg.payload = [queryDel, updateDel, { "upsert": false }];
    msg.operation = "updateOne";
    return [msg, null];
}

return null;
